 public static class Player extends FrameLayout {public boolean releaseOnDetachFromWindow=true;boolean running=true;int starts,pauses,uris,seeks;long position=12345;Player(android.content.Context c){super(c);}public boolean isPlaying(){return running;}public long getCurrentPosition(){return position;}public long getDuration(){return 100000;}public void start(){running=true;starts++;}public void pause(){running=false;pauses++;}public void setReleaseOnDetachFromWindow(boolean v){releaseOnDetachFromWindow=v;}public void setVideoURI(android.net.Uri u){uris++;}public void seekTo(long p){position=p;seeks++;}}
