 @Test public void normalWindowIsHiddenBeforeItCanDrawAndStaleTokenCannotHideOtherScreens(){Activity browser=Robolectric.buildActivity(Activity.class).setup().get();DirectBootstrap238.Pending p=new DirectBootstrap238.Pending(77,browser);DirectBootstrap238.pending=p;Activity source=Robolectric.buildActivity(Activity.class,new Intent().putExtra(DirectBootstrap238.TOKEN,77L)).setup().get();DirectBootstrap238.prepare(source);assertEquals(0,source.getWindow().getAttributes().alpha,.001);assertSame(source,p.source);Activity unrelated=Robolectric.buildActivity(Activity.class).setup().get();DirectBootstrap238.prepare(unrelated);assertEquals(1,unrelated.getWindow().getAttributes().alpha,.001);DirectBootstrap238.cancel(p,false);assertEquals(1,source.getWindow().getAttributes().alpha,.001);assertNull(DirectBootstrap238.pending);}
 @Test public void directMiniRestoresTheExactPlayerPositionAndPauseStateWithoutMediaCommands()throws Exception{Activity browser=Robolectric.buildActivity(Activity.class).setup().get();MiniSession225.track(browser);com.sauzask.nicoid.NicoidVideoActivity source=Robolectric.buildActivity(com.sauzask.nicoid.NicoidVideoActivity.class).setup().get();Owner owner=new Owner();owner.A1=source;Player video=new Player(source);video.running=false;com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView texture=new com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView(source);video.addView(texture);LinearLayout original=new LinearLayout(source);original.addView(video,new LinearLayout.LayoutParams(500,280));owner.a0=video;source.v=owner;source.setContentView(original);assertTrue(MiniSession225.beginMinimized(owner,browser));MiniSession225.Session s=current();assertTrue(s.openingDirect);callbacks().onActivityResumed(source);assertSame(s,current());s.attach(browser);assertFalse(s.openingDirect);assertSame(video,s.video);assertSame(s.panel,video.getParent());assertTrue(MiniSession225.retainNavigation(source));s.restore();Intent restore=Shadows.shadowOf(browser).getNextStartedActivity();assertNotNull(restore);assertTrue((restore.getFlags()&Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)!=0);assertFalse(restore.hasExtra("nicoid_playback_transfer"));callbacks().onActivityResumed(source);assertNull(current());assertSame(original,video.getParent());assertEquals(12345,video.position);assertFalse(video.running);assertEquals(0,video.uris);assertEquals(0,video.seeks);assertEquals(0,video.starts);assertEquals(0,video.pauses);assertEquals(1,source.getWindow().getAttributes().alpha,.001);}
 @Test public void closingPreparingSessionCancelsNavigationAndRetainedOwner()throws Exception{Activity browser=Robolectric.buildActivity(Activity.class).setup().get();MiniSession225.track(browser);Activity source=Robolectric.buildActivity(Activity.class).setup().get();Owner owner=new Owner();owner.A1=source;Player v=new Player(source);v.addView(new com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView(source));LinearLayout original=new LinearLayout(source);original.addView(v);owner.a0=v;assertTrue(MiniSession225.beginMinimized(owner,browser));MiniSession225.Session s=current();s.close(false);s.navigateDirect.run();assertNull(current());assertNull(Shadows.shadowOf(source).getNextStartedActivity());assertSame(original,v.getParent());assertFalse(MiniSession225.retainNavigation(source));}
 @Test public void directIdentifiersAreValidatedAndMediaTransferExtrasAreRemoved(){Intent valid=new Intent().putExtra("url","https://www.nicovideo.jp/watch/sm42?x=1");assertEquals("sm42",DirectBootstrap238.id(valid));assertNull(DirectBootstrap238.id(new Intent().putExtra("url","invalid")));assertNull(DirectBootstrap238.id(new Intent()));}
 @Test public void retainedOutputIsNotReleasedBeforeDestinationTextureBecomesAvailable(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();Player video=new Player(a);com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView texture=new com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView(a);video.addView(texture);a.setContentView(video);MiniSession225.SurfaceKeeper keeper=new MiniSession225.SurfaceKeeper(texture);keeper.restore(video);Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(keeper.closed);assertNotNull(keeper.saved);texture.available=true;keeper.onSurfaceTextureAvailable(texture.surface,100,100);Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(keeper.closed);assertEquals(0,video.uris);assertEquals(0,video.starts);}
